def inr_format(n):
    s = str(n)
    result = []
    for i in range(len(s), 0, -3):
        group = s[i-3:i] if i-3 >= 0 else s[:i]
        result.append(group)
    return ','.join(reversed(result))

def inr_format(n):
    s = str(n)
    result = []
    for i in range(len(s)-1, -1, -1):
        if (len(s) - i) % 3 == 0 and i != 0:
            result.append(',')
        result.append(s[i])
    return ''.join(reversed(result))

